solution.ring.py:
class RingBuffer:
    def __init__(self, capacity):
        self.capacity = capacity
        self._buf = []

    def append(self, x):
        self._buf.append(x)
        if len(self._buf) > self.capacity:
            self._buf.pop(0)

    def items(self):
        return list(self._buf)

solution.stats.py:
from ring import RingBuffer


def windowed_mean(values, size):
    buf = RingBuffer(size)
    out = []
    for v in values:
        buf.append(v)
        items = buf.items()
        if len(items) == size:
            out.append(sum(items) / size)
    return out

