solution.lexer.py:
import re
from tokens import Token, KEYWORDS


def tokenize(src):
    out = []
    for piece in re.findall(r'[A-Za-z_][A-Za-z0-9_]*|[0-9]+|[(){};=]', src):
        if piece in KEYWORDS:
            out.append(Token('kw', piece))
        elif piece[0].isdigit():
            out.append(Token('num', piece))
        elif piece[0].isalpha() or piece[0] == '_':
            out.append(Token('id', piece))
        else:
            out.append(Token('punct', piece))
    return out

solution.interp.py:
from ops import OPS


def run(prog):
    stack = []
    for tok in prog.split():
        if tok == 'dup':
            stack.append(stack[-1])
        elif tok in OPS:
            b = stack.pop()
            a = stack.pop()
            stack.append(OPS[tok](a, b))
        elif tok.lstrip('-').isdigit():
            stack.append(int(tok))
        else:
            raise ValueError(f'unknown token: {tok}')
    return stack

